package http_test

// The differential against the reference: every request of testdata/reference/cases.json goes
// through /mcp here and is compared with what the reference's own handler answered
// (testdata/reference/answers.json, generated by testdata/reference/gen). Equal means: the same
// status and Allow header; where the reference answered application/json, the same bytes; where
// it answered an event stream (its classic POST answers; ours are JSON, ruling 11), the same
// JSON-RPC message(s) as JSON documents (the answers of a batch in any order); an empty body where
// it answered none.

import (
	"bytes"
	"encoding/json"
	"os"
	"path/filepath"
	"reflect"
	"sort"
	"strings"
	"testing"

	"github.com/ai-pipes/mcp-registry/internal/modules/gateway"
)

type refCase struct {
	Name    string            `json:"name"`
	Method  string            `json:"method"`
	Headers map[string]string `json:"headers"`
	Body    string            `json:"body"`
}

type refAnswer struct {
	Name        string `json:"name"`
	Status      int    `json:"status"`
	ContentType string `json:"contentType"`
	Allow       string `json:"allow"`
	Body        string `json:"body"`
}

// acceptedDifferences are the rows that differ on purpose (section 6 of the task report).
var acceptedDifferences = map[string]string{
	// encoding/json refuses nesting deeper than 10000 levels as invalid JSON (-32700); JSON.parse
	// reads it and the classifier refuses the message (-32600).
	"deep nesting": "-32700 instead of -32600",
	// The reference classifies every element; Go stops reading at the 101st element, so a flaw in
	// the 101st or a later element is answered with the size refusal.
	"batch 101, invalid 101st": "the cap is answered before the 101st element is judged",
	"batch 102, invalid 102nd": "the cap is answered before the 102nd element is judged",
	"batch 102, claim 102nd":   "the cap is answered before the 102nd element is judged",
}

func readJSONFile(t *testing.T, name string, v any) {
	t.Helper()
	raw, err := os.ReadFile(filepath.Join("testdata", "reference", filepath.Base(name)))
	if err != nil {
		t.Fatal(err)
	}
	if err := json.Unmarshal(raw, v); err != nil {
		t.Fatalf("%s: %v", name, err)
	}
}

// streamMessages is the data of the message events of an event-stream body: one JSON value, or an
// array of them when there are several.
func streamMessages(t *testing.T, body string, batch bool) any {
	t.Helper()
	var msgs []any
	for _, event := range strings.Split(strings.ReplaceAll(body, "\r\n", "\n"), "\n\n") {
		var data []string
		for _, line := range strings.Split(event, "\n") {
			if rest, ok := strings.CutPrefix(line, "data:"); ok {
				data = append(data, strings.TrimPrefix(rest, " "))
			}
		}
		if p := strings.Join(data, "\n"); strings.TrimSpace(p) != "" {
			var m any
			if err := json.Unmarshal([]byte(p), &m); err != nil {
				t.Fatalf("event %q: %v", p, err)
			}
			msgs = append(msgs, m)
		}
	}
	if len(msgs) == 1 && !batch {
		return msgs[0]
	}
	return msgs
}

// inAnyOrder sorts the answers of a batch by their JSON text: the reference writes them in the
// order they complete, Go in the order of the requests (JSON-RPC leaves the order open).
func inAnyOrder(v any, batch bool) any {
	list, ok := v.([]any)
	if !batch || !ok {
		return v
	}
	keys := make([]string, len(list))
	for i, m := range list {
		b, _ := json.Marshal(m)
		keys[i] = string(b)
	}
	sort.Strings(keys)
	return keys
}

func TestTheReferenceAnswersTheseRequests(t *testing.T) {
	var cases []refCase
	var answers []refAnswer
	readJSONFile(t, "cases.json", &cases)
	readJSONFile(t, "answers.json", &answers)
	if len(cases) != len(answers) || len(cases) < 150 {
		t.Fatalf("%d cases, %d answers", len(cases), len(answers))
	}
	e := newEnv(t)
	e.gw.result = gateway.ToolResult{Content: json.RawMessage(`[{"type":"text","text":"called"}]`)}
	differ := 0
	for i, c := range cases {
		want := answers[i]
		if want.Name != c.Name {
			t.Fatalf("answer %d is %q, case %q", i, want.Name, c.Name)
		}
		hdr := []string{"Authorization: Bearer " + aliceToken, "Content-Type:", "Accept:"}
		for k, v := range c.Headers {
			hdr = append(hdr, k+": "+v)
		}
		got := e.do(t, c.Method, "/mcp", c.Body, hdr...)
		problem := ""
		switch {
		case got.status != want.Status:
			problem = "status"
		case got.header.Get("Allow") != want.Allow:
			problem = "Allow"
		case want.Body == "" && len(got.body) != 0:
			problem = "body (none expected)"
		case strings.HasPrefix(want.ContentType, "application/json") && (!bytes.Equal(got.body, []byte(want.Body)) || got.header.Get("Content-Type") != "application/json"):
			problem = "body bytes"
		case strings.HasPrefix(want.ContentType, "text/event-stream"):
			var mine any
			batch := strings.HasPrefix(strings.TrimSpace(c.Body), "[")
			if err := json.Unmarshal(got.body, &mine); err != nil || !reflect.DeepEqual(inAnyOrder(mine, batch), inAnyOrder(streamMessages(t, want.Body, batch), batch)) {
				problem = "message"
			}
		}
		if problem == "" {
			if _, accepted := acceptedDifferences[c.Name]; accepted {
				t.Errorf("%s: equal to the reference, remove it from acceptedDifferences", c.Name)
			}
			continue
		}
		if _, accepted := acceptedDifferences[c.Name]; accepted {
			continue
		}
		differ++
		t.Errorf("%s: %s differs\n got %d %s %.400s\nwant %d %s %.400s", c.Name, problem, got.status, got.header.Get("Content-Type"), got.body, want.Status, want.ContentType, want.Body)
	}
	t.Logf("%d requests compared, %d accepted differences, %d unexpected", len(cases), len(acceptedDifferences), differ)
}
